def searchBST(root, val):
    while root and root.val != val:
        root = root.left if val < root.val else root.right
    return root





def fib_dp(n):
    if n <= 1:
        return n
    dp = [0] * (n + 1)
    dp[0] = 0
    dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]









